const req = $input.first().json;
const body = req.body && typeof req.body === 'object' ? req.body : {};
const errors = [];
const topics = Array.isArray(body.topics) ? body.topics : [];
if (!topics.length) errors.push('topics must be a non-empty array');
if (topics.length > 50) errors.push('a batch can hold at most 50 topics');
const defaults = body.defaults && typeof body.defaults === 'object' ? body.defaults : {};
const concurrency = body.concurrency === undefined ? 3 : Number(body.concurrency);
if (!Number.isInteger(concurrency) || concurrency < 1 || concurrency > 5) {
  errors.push('concurrency must be a whole number between 1 and 5');
}
const items = topics.slice(0, 50).map(entry => Object.assign({}, defaults, typeof entry === 'string' ? { topic: entry } : (entry || {})));
items.forEach((item, i) => {
  if (typeof item.topic !== 'string' || !item.topic.trim()) errors.push('topics[' + i + '] needs a topic');
});

const batchId = 'batch-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + Math.random().toString(36).slice(2, 8);
const host = (req.headers && req.headers.host) || 'localhost:5678';
return [{
  json: {
    valid: errors.length === 0,
    errors,
    batch_id: batchId,
    concurrency,
    items,
    submitted_at: $now.toISO(),
    started_ms: Date.now(),
    file_path: '/home/node/.n8n-files/outputs/' + batchId + '.json',
    accepted_body: {
      batch_id: batchId,
      status: 'accepted',
      count: items.length,
      concurrency,
      status_url: 'http://' + host + '/webhook/content/batch-status?batch_id=' + batchId,
      summary_path: 'outputs/' + batchId + '.json'
    }
  }
}];

const p = $input.first().json;
const manifest = {
  batch_id: p.batch_id,
  status: 'running',
  submitted_at: p.submitted_at,
  count: p.items.length,
  concurrency: p.concurrency,
  topics: p.items.map(item => item.topic)
};
return [{
  json: { path: p.file_path },
  binary: { data: { data: Buffer.from(JSON.stringify(manifest, null, 2), 'utf8').toString('base64'), mimeType: 'application/json', fileName: p.batch_id + '.json', fileExtension: 'json' } }
}];

const p = $('Plan Batch').first().json;
return p.items.map((item, index) => ({
  json: { index, request_id: p.batch_id + '-' + String(index + 1).padStart(2, '0'), body: item }
}));

const p = $('Plan Batch').first().json;
const results = $input.all().map((item, index) => {
  const r = item.json;
  const body = r.body && typeof r.body === 'object' ? r.body : {};
  const request = p.items[index] || {};
  const failure = r.error ? (r.error.message || String(r.error)) : null;
  return {
    index: index + 1,
    topic: request.topic,
    http_status: r.statusCode || null,
    status: body.status || (failure ? 'error' : 'unknown'),
    run_id: body.run_id || null,
    style: body.style || null,
    title: body.title || null,
    word_count: body.word_count || null,
    duration_ms: body.timings_ms ? body.timings_ms.total : null,
    cost_usd: body.cost_usd || 0,
    fallback_used: Boolean(body.models && body.models.fallback_used),
    article: body.files ? body.files.article : null,
    error: body.error || (body.errors ? body.errors.join('; ') : null) || body.detail || failure
  };
});
const durations = results.map(r => r.duration_ms).filter(d => typeof d === 'number').sort((a, b) => a - b);
const percentile = q => (durations.length ? durations[Math.min(durations.length - 1, Math.ceil(q * durations.length) - 1)] : null);
const byStatus = {};
results.forEach(r => { byStatus[r.status] = (byStatus[r.status] || 0) + 1; });
const summary = {
  batch_id: p.batch_id,
  status: 'completed',
  submitted_at: p.submitted_at,
  completed_at: $now.toISO(),
  wall_time_ms: Date.now() - p.started_ms,
  count: results.length,
  concurrency: p.concurrency,
  by_status: byStatus,
  runs_within_5_min: durations.filter(d => d <= 300000).length,
  latency_ms: { p50: percentile(0.5), p95: percentile(0.95), max: durations.length ? durations[durations.length - 1] : null },
  cost_usd_total: Number(results.reduce((sum, r) => sum + r.cost_usd, 0).toFixed(4)),
  items: results
};
return [{
  json: { path: p.file_path, summary },
  binary: { data: { data: Buffer.from(JSON.stringify(summary, null, 2), 'utf8').toString('base64'), mimeType: 'application/json', fileName: p.batch_id + '.json', fileExtension: 'json' } }
}];

const id = String(($input.first().json.query || {}).batch_id || '');
// Strict pattern: the id becomes part of a file path, so nothing else is allowed through.
const valid = /^batch-\d{8}-\d{6}-[a-z0-9]{1,8}$/.test(id);
return [{ json: { valid, batch_id: id, path: '/home/node/.n8n-files/outputs/' + (valid ? id : 'invalid') + '.json' } }];

const item = $input.first();
if (!item || !item.binary || !item.binary.data) {
  return [{ json: { status_code: 404, body: { status: 'not_found', error: 'Unknown batch_id' } } }];
}
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { status_code: 200, body: JSON.parse(buffer.toString('utf8')) } }];
